/** Origin of a day of the schedule after the rotation writes it: generated by the rotation, or set by hand. */
export type ShiftOrigin = 'GENERATED' | 'MANUAL';

/** Why a row of the preview ended up with its final code (RotationRow.status). */
export type RotationRowStatus =
  | 'NEW'
  | 'REGENERATED'
  | 'REPLACED_MANUAL'
  | 'KEPT_MANUAL'
  | 'SKIPPED_NOVELTY'
  | 'UNCHANGED';

/** How the phase of a titular was obtained (RotationTitularPhase.source). */
export type RotationPhaseSource = 'DEDUCED' | 'PROVIDED' | 'SUGGESTED';

/** Body of POST /api/shifts/schedule/rotation/preview. month is "yyyy-MM". */
export interface RotationPreviewRequest {
  month: string;
  /** Phase (0 to 5) chosen for some titulares, keyed by worker id; it wins over the deduced one. */
  phases?: Record<string, number>;
  /** Rewrite the days set by hand too. */
  replaceManual: boolean;
}

/** Same shape as the preview request, plus the preview's gridVersion. */
export interface RotationConfirmRequest {
  month: string;
  phases?: Record<string, number>;
  replaceManual: boolean;
  gridVersion: string;
}

/** Phase of one titular on the first day to generate (RotationTitularPhase). */
export interface RotationTitularPhase {
  workerId: string;
  fullName: string;
  /** 0 and 1 DIA, 2 and 3 NOCHE, 4 and 5 DESCANSO on the first day to generate. */
  phase: number;
  source: RotationPhaseSource;
  /** True when the administrator must choose the phase before confirming. */
  needsChoice: boolean;
  /** Recent days of the grid that do not fit this phase. */
  errors: number;
}

/** One worker on one day of the proposed grid (RotationRow). */
export interface RotationRow {
  workerId: string;
  fullName: string;
  shiftCode: string;
  origin: ShiftOrigin;
  status: RotationRowStatus;
}

/** Coverage of one day of the proposed grid (RotationCoverage). */
export interface RotationCoverage {
  covered: boolean;
  dayCovered: boolean;
  nightCovered: boolean;
  supportCovered: boolean;
  uncoveredHours: string[];
}

/** One day of the proposed grid (RotationDay). */
export interface RotationDay {
  date: string;
  rows: RotationRow[];
  coverage: RotationCoverage;
}

/** A day set by hand that the preview keeps (RotationKeptDay). */
export interface RotationKeptDay {
  workerId: string;
  fullName: string;
  date: string;
  currentCode: string;
  proposedCode: string;
}

/** One warning of the preview; never blocks the confirmation (RotationWarning). */
export interface RotationWarning {
  code: string;
  message: string;
}

/** Days generated, kept and left without full coverage (RotationCounts). */
export interface RotationCounts {
  generated: number;
  kept: number;
  uncovered: number;
}

/** Preview of the rotation of a month. Nothing has been saved (RotationPreviewResponse). */
export interface RotationPreviewResponse {
  month: string;
  /** Null when there are no days left to generate. */
  from: string | null;
  to: string | null;
  phases: RotationTitularPhase[];
  days: RotationDay[];
  kept: RotationKeptDay[];
  /** Dates left untouched because they have novelties of the day staff. */
  skippedDates: string[];
  warnings: RotationWarning[];
  counts: RotationCounts;
  /** Fingerprint to send with the confirmation. */
  gridVersion: string;
}

/** Result of confirming the rotation of a month (RotationResultResponse). */
export interface RotationResultResponse {
  generated: number;
  kept: number;
  uncoveredDates: string[];
}
